draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';

  // head
  ctx.beginPath();
  ctx.arc(W/2, H/2, 30 + 10 * Math.sin(t), 0, 2 * Math.PI);
  ctx.stroke();

  // body
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 30 + 10 * Math.sin(t));
  ctx.lineTo(W/2, H/2 + 80 + 20 * Math.cos(t));
  ctx.stroke();

  // arms
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50 + 15 * Math.sin(t));
  ctx.lineTo(W/2 - 30 + 20 * Math.cos(t), H/2 + 70 + 10 * Math.sin(t));
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50 + 15 * Math.sin(t));
  ctx.lineTo(W/2 + 30 - 20 * Math.cos(t), H/2 + 70 + 10 * Math.sin(t));
  ctx.stroke();

  // legs
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 80 + 20 * Math.cos(t));
  ctx.lineTo(W/2 - 20 + 15 * Math.sin(t), H/2 + 120 - 10 * Math.cos(t));
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 80 + 20 * Math.cos(t));
  ctx.lineTo(W/2 + 20 - 15 * Math.sin(t), H/2 + 120 - 10 * Math.cos(t));
  ctx.stroke();

  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.fillStyle = 'black';
  ctx.fillText('Inspired', W/2, H/2 - 50 + 10 * Math.cos(t));
  ctx.fillText('Motivated', W/2, H/2 - 20 + 10 * Math.sin(t));
  ctx.fillText('Energized', W/2, H/2 + 10 + 10 * Math.cos(t));

  ctx.restore();
}
